<script lang="ts">
 import {enhance} from '$app/forms';
 import {weatherDays,celsius} from './weather.mjs';
 let {zone,cached,products,enhanced,busy}:{zone:any,cached:any,products:any,enhanced:any,busy:boolean}=$props();
 let payload=$derived(cached?.data||products.getForecastWeather?.value);
 let days=$derived(weatherDays(payload));
 let current=$derived(payload?.normal?.current||payload?.current||products.getPresentWeather?.value?.current);
 let retrieved=$derived(cached?.fetched_at||products.getForecastWeather?.fetchedAt);
 let limits=$derived(days.flatMap((d:any)=>[d.min,d.max]).filter((v:any)=>v!==null));
 let low=$derived(limits.length?Math.min(...limits)-2:0),high=$derived(limits.length?Math.max(...limits)+2:1);
 const y=(v:number)=>140-(v-low)/(high-low)*110;
 const x=(i:number)=>40+i*80;
 let segments=$derived(days.flatMap((d:any,i:number)=>i>0&&days[i-1].max!==null&&d.max!==null?[`${x(i-1)},${y(days[i-1].max!)} ${x(i)},${y(d.max)}`]:[]));
 const dayText=(dt:number)=>new Date(dt*1000).toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short',timeZone:'Africa/Harare'});
 const reading=(n:number|null)=>n===null?'Unavailable':`${n.toFixed(0)}°`;
</script>
<section class="p-card weather-intro"><div><p class="p-kicker">FIELD WEATHER / {zone.name}</p><h2>Plan the week around your land.</h2><p>Forecast at the centre of this field’s mapped extent. Conditions can vary across your farm.</p></div><form method="POST" action="?/weather" use:enhance={enhanced}><input type="hidden" name="zone" value={zone.id}/><button class="p-button" disabled={busy}>{days.length?'Refresh forecast':'Load field forecast'}</button></form></section>
{#if days.length}
 <section class="weather-board"><div class="weather-now"><p class="p-kicker">{current?'CURRENT CONDITIONS':'FIRST FORECAST DAY'}</p><strong>{current?reading(celsius(current.temp)):reading(days[0].max)}<small>C</small></strong><p>{current?.weather?.[0]?.description||days[0].description}</p><span>{zone.name}</span><p class="p-caption">Retrieved {retrieved?new Date(retrieved).toLocaleString('en-GB',{timeZone:'Africa/Harare'}):'time unavailable'}</p></div><div class="weather-chart"><p class="p-kicker">DAILY HIGH / °C</p><svg viewBox="0 0 580 180" role="img" aria-label="Daily high temperature trend; full forecast values follow below">{#each segments as points}<polyline {points} fill="none" stroke="#bfe56b" stroke-width="3"/>{/each}{#each days as d,i}{#if d.max!==null}<circle cx={x(i)} cy={y(d.max)} r="4" fill="#bfe56b"/><text x={x(i)} y={y(d.max)-12} text-anchor="middle">{d.max.toFixed(0)}°</text>{/if}<text x={x(i)} y="174" text-anchor="middle">{new Date(d.timestamp*1000).toLocaleDateString('en',{weekday:'short',timeZone:'Africa/Harare'})}</text>{/each}</svg></div></section>
 <div class="weather-days">{#each days as day}<article class="p-card"><p class="p-kicker">{dayText(day.timestamp)}</p><h3>{day.description}</h3><p class="temps"><strong>{reading(day.max)}</strong> <span>{reading(day.min)}</span></p><div class="rain-track" aria-hidden="true"><span style:width={`${day.probability??0}%`}></span></div><dl><div><dt>Chance of rain</dt><dd>{day.probability===null?'Unavailable':day.probability+'%'}</dd></div><div><dt>Rain amount</dt><dd>{day.rain===null?'Not returned':day.rain+' mm'}</dd></div><div><dt>Wind</dt><dd>{day.wind===null?'Unavailable':day.wind+' m/s'}</dd></div><div><dt>Humidity</dt><dd>{day.humidity===null?'Unavailable':day.humidity+'%'}</dd></div></dl></article>{/each}</div>
{:else}<section class="p-card p-empty"><h2>Your forecast starts with this field.</h2><p>Load the forecast above. You can access weather before satellite monitoring is approved.</p></section>{/if}
<style>
 .weather-intro{display:flex;gap:25px;justify-content:space-between;align-items:center}.weather-intro p{max-width:650px}.weather-board{display:grid;grid-template-columns:1fr 2fr;background:#123f33;color:#fff;border-radius:18px;margin-bottom:24px;padding:32px;gap:32px}.weather-board .p-kicker{color:#cee2af}.weather-now>strong{font-size:64px;font-weight:500;line-height:1.2}.weather-now strong small{font-size:22px}.weather-now>span{font-size:14px}.weather-now .p-caption{color:#c3d1c3}.weather-chart{align-self:center;min-width:0}.weather-chart svg{width:100%;overflow:visible}.weather-chart text{fill:#f7f6ec;font-size:12px}.weather-days{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:14px}.weather-days .p-card{padding:22px;margin:0}.weather-days h3{font-size:17px;min-height:46px;text-transform:capitalize}.temps strong{font-size:32px}.temps span{color:#657768}.rain-track{height:5px;background:#e7eee4;border-radius:4px}.rain-track span{display:block;background:#6c9caf;height:100%;border-radius:4px}dl{font-size:12px}dl div{display:flex;flex-wrap:wrap;justify-content:space-between;gap:8px;margin-top:14px}dd{margin:0;font-weight:600}@media(max-width:800px){.weather-board{grid-template-columns:1fr;padding:24px}.weather-intro{align-items:start;flex-direction:column}.weather-days{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:380px){.weather-days{grid-template-columns:1fr}}
</style>
